#pragma comment(lib,"Psapi.lib")

using namespace Aevrynd;
static std::uint64_t Median(std::vector<std::uint64_t> values){std::ranges::sort(values);return values[values.size()/2];}
static MaterialTextureSetDefinition3D TerrainTextures(){const std::filesystem::path root=std::filesystem::path{AEVRYND_SOURCE_DIR}/"engine"/"assets"/"material-packs";MaterialTextureSetDefinition3D result;result.baseColorPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_Color.jpg";result.roughnessPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_Roughness.jpg";result.normalPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_NormalDX.jpg";result.maximumResolution=1024;result.additionalLayers[0]={root/"poly-haven/aerial_ground_rock/1k/base-color.jpg",root/"poly-haven/aerial_ground_rock/1k/roughness.jpg",root/"poly-haven/aerial_ground_rock/1k/normal-dx.jpg"};result.additionalLayers[1]={root/"poly-haven/rock_surface/1k/base-color.jpg",root/"poly-haven/rock_surface/1k/roughness.jpg",root/"poly-haven/rock_surface/1k/normal-dx.jpg"};return result;}

int main(){
    constexpr std::size_t Iterations=200000;TerrainDistanceMaterialSettings3D settings{};volatile float sink{};const auto cpuStart=std::chrono::steady_clock::now();for(std::size_t index=0;index<Iterations;++index)sink=sink+TerrainDetailWeight3D(float(index%512),settings)*TerrainMacroVariation3D({float(index),float(index/7)},settings);const auto cpuNanoseconds=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-cpuStart).count();
    HWND window=CreateWindowExW(0,L"STATIC",L"AevryndTerrainDistanceMaterialBenchmark",WS_OVERLAPPED,0,0,640,360,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);if(!window)return 1;D3D12Renderer renderer;renderer.Initialize(window,640,360,640,360,false);renderer.SetQualitySettings({false,false,false,false});const std::uint32_t normal=PackNormalSnorm8({0,1,0}),color=PackColorRgba8({1,1,1,.55f});const std::array<Vertex3D,4> vertices={Vertex3D{-1,-1,.2f,normal,color,0,1},Vertex3D{-1,1,.8f,normal,color,0,0},Vertex3D{1,1,.8f,normal,color,1,0},Vertex3D{1,-1,.2f,normal,color,1,1}};const std::array<std::uint32_t,6> indices={0,1,2,0,2,3};const auto mesh=renderer.CreateMesh(vertices,indices);const auto textures=renderer.CreateMaterialTextureSet(TerrainTextures());if(!mesh||!textures)return 2;DrawList draw;draw.SetViewProjection(Matrix4::Identity());draw.SetDirectionalShadowMapEnabled(false);draw.SetBackfaceCulling(false);draw.MeshInstance(mesh,Matrix4::Identity(),{1,1,1,1},{.9f,0,0,1},MeshRenderLayer3D::Opaque,textures,4.f,false,MaterialClass3D::Terrain,std::numeric_limits<float>::quiet_NaN(),false);
    struct Measurement{std::uint64_t gpu{},cpu{};};auto run=[&](bool enabled){TerrainDistanceMaterialSettings3D selected=settings;selected.enabled=enabled;selected.detailFadeStart=0;selected.detailFadeEnd=.01f;draw.SetTerrainDistanceMaterial(selected);std::vector<std::uint64_t> gpu,cpu;for(unsigned frame=0;frame<72;++frame){const auto begin=std::chrono::steady_clock::now();renderer.Render(draw,{.08f,.14f,.2f,1});const auto elapsed=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count();if(frame>=16){cpu.push_back(std::uint64_t(elapsed));const auto stats=renderer.GetStats();if(stats.lastGpuFrameNanoseconds)gpu.push_back(stats.lastGpuFrameNanoseconds);}}return Measurement{gpu.empty()?0:Median(gpu),Median(cpu)};};const Measurement full=run(false),distanceLod=run(true);renderer.WaitIdle();PROCESS_MEMORY_COUNTERS_EX memory{};GetProcessMemoryInfo(GetCurrentProcess(),reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&memory),sizeof(memory));const RendererStats stats=renderer.GetStats();const std::size_t tracked=renderer.MemoryStats().trackedCapacityBytes;renderer.DestroyMaterialTextureSet(textures);renderer.DestroyMesh(mesh);renderer.WaitIdle();renderer.TrimTransientMemory();const RendererStats released=renderer.GetStats();DestroyWindow(window);const double cpuPerQuery=double(cpuNanoseconds)/double(Iterations);std::cout<<"cpu_reference_ns_per_query="<<cpuPerQuery<<" gpu_full_ns="<<full.gpu<<" gpu_distance_lod_ns="<<distanceLod.gpu<<" gpu_delta_ns="<<std::int64_t(distanceLod.gpu)-std::int64_t(full.gpu)<<" render_cpu_full_ns="<<full.cpu<<" render_cpu_lod_ns="<<distanceLod.cpu<<" working_set_bytes="<<memory.WorkingSetSize<<" tracked_bytes="<<tracked<<" frame_alloc_bytes="<<stats.lastUploadBytes<<" texture_bytes="<<stats.residentTextureBytes<<" released_texture_bytes="<<released.residentTextureBytes<<" near_samples=9 far_samples=3 sink="<<sink<<'\n';return cpuPerQuery>250.0||!stats.lastSubmittedTerrainInstances||TerrainMaterialTextureSamples3D(300,true,settings)!=3||released.residentTextureBytes?3:0;
}
